}// Shared helpers for ENG-1955 live verification modules.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const DIR = path.dirname(fileURLToPath(import.meta.url));
export const STATE_PATH = path.join(DIR, "state.json");
export const readState = () => (fs.existsSync(STATE_PATH) ? JSON.parse(fs.readFileSync(STATE_PATH, "utf8")) : {});
export const writeState = (s) => fs.writeFileSync(STATE_PATH, JSON.stringify(s, null, 2));

export const REL = { supports: "2CcUT958c", informs: "yd7pX2bvn" };
export const NODE = { claim: "eXm8WyS02", question: "WwAi4HfE0", evidence: "-YVlXUsDF" };

export const waitFor = async (page, fn, arg, timeout = 60000, label = "condition") => {
  const start = Date.now();
  for (;;) {
    if (await page.evaluate(fn, arg).catch(() => false)) return true;
    if (Date.now() - start > timeout) throw new Error(`timeout waiting for ${label}`);
    await page.waitForTimeout(300);
  }
};
export const tryWait = async (...a) => waitFor(...a).catch(() => false);

// Production builds don't expose window.tldrawApps, so find the editor through React fibers.
export const installEditorFinder = (page) =>
  page.evaluate(() => {
    const isEd = (v) => v && typeof v === "object" && typeof v.getCurrentPageShapes === "function" && v.store;
    window.__eng1955Editors = () =>
      Array.from(document.querySelectorAll(".roamjs-tldraw-canvas-container")).map((c) => {
        const el = c.querySelector(".tl-canvas") || c.querySelector(".tl-container");
        if (!el) return null;
        const key = Object.keys(el).find((k) => k.startsWith("__reactFiber$"));
        let f = key ? el[key] : null;
        for (let i = 0; f && i < 400; i += 1, f = f.return) {
          const p = f.memoizedProps;
          if (isEd(p?.editor)) return p.editor;
          if (isEd(p?.value)) return p.value;
        }
        return null;
      });
    window.__eng1955Ed = () => {
      const main = document.querySelector(".roam-article .roamjs-tldraw-canvas-container, .rm-article-wrapper .roamjs-tldraw-canvas-container");
      const all = Array.from(document.querySelectorAll(".roamjs-tldraw-canvas-container"));
      return window.__eng1955Editors()[main ? all.indexOf(main) : 0] || null;
    };
    return true;
  });

export const closeRoamDialogs = async (page) => {
  for (let i = 0; i < 4; i += 1) {
    const open = await page.evaluate(() => Boolean(document.querySelector(".bp3-dialog, .rm-settings")));
    if (!open) return;
    await page.keyboard.press("Escape");
    await page.waitForTimeout(400);
  }
};

export const uidOf = (page, title) =>
  page.evaluate((t) => window.roamAlphaAPI.q(`[:find ?u . :in $ ?t :where [?p :node/title ?t] [?p :block/uid ?u]]`, t), title);

export const openPage = async (page, uid) => {
  await page.evaluate((u) => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid: u } }), uid);
};

// Records relevant to relations from the live editor store.
export const snapshotEditor = (page, title) =>
  page.evaluate((t) => {
    const ed = window.__eng1955Ed();
    if (!ed) return null;
    const recs = ed.store.allRecords();
    const shapes = recs.filter((r) => r.typeName === "shape").map((r) => ({
      id: r.id, type: r.type, relationTypeId: r.props?.relationTypeId, text: r.props?.text ?? r.props?.title, nodeTypeId: r.props?.nodeTypeId, bend: r.props?.bend,
    }));
    const bindings = recs.filter((r) => r.typeName === "binding").map((r) => ({ id: r.id, type: r.type, fromId: r.fromId, toId: r.toId, terminal: r.props?.terminal }));
    return {
      shapes, bindings,
      cloudIcon: Boolean(document.querySelector(".roamjs-tldraw-canvas-container [title='Using cloud canvas']")),
      rendered: Array.from(document.querySelectorAll(".roamjs-tldraw-canvas-container .tl-shape")).map((e) => `${e.id}|${e.getAttribute("data-shape-type")}`),
    };
  }, title);

export const rawPageStore = (page, uid) =>
  page.evaluate((u) => {
    const props = window.roamAlphaAPI.pull("[:block/props]", [":block/uid", u])?.[":block/props"] || {};
    const q = props[":roamjs-query-builder"] || props["roamjs-query-builder"] || {};
    const get = (o, k) => o?.[`:${k}`] ?? o?.[k];
    const tl = get(q, "tldraw");
    const store = get(tl, "store") || {};
    const recs = Object.values(store).map((r) => ({ id: get(r, "id"), typeName: get(r, "typeName"), type: get(r, "type"), relationTypeId: get(get(r, "props"), "relationTypeId") }))
      .filter((r) => r.typeName === "shape" || r.typeName === "binding");
    return { syncMode: get(q, "canvasSyncMode"), migrationState: get(q, "canvasSyncMigrationState"), schemaSeq: JSON.stringify(get(get(tl, "schema"), "sequences") || {}).slice(0, 600), recs };
  }, uid);

export const attachLogs = (page) => {
  const logs = [];
  page.on("console", (m) => { if (["error", "warning"].includes(m.type())) logs.push(`[${m.type()}] ${m.text().slice(0, 300)}`); });
  page.on("pageerror", (e) => logs.push(`[pageerror] ${String(e?.message || e).slice(0, 300)}`));
  return logs;
};
export const relevant = (logs) => logs.filter((l) => /valid|shape type|binding type|unknown|sync|tldraw|relation|migrat|schema/i.test(l)).slice(0, 25);

export const canvasState = (page) =>
  page.evaluate(() => {
    const c = document.querySelector(".roamjs-tldraw-canvas-container");
    return {
      container: Boolean(c),
      tlCanvas: Boolean(c?.querySelector(".tl-canvas")),
      text: (c?.innerText || "").replace(/\s+/g, " ").slice(0, 300),
      editorFound: Boolean(window.__eng1955Ed?.()),
      shapeCount: window.__eng1955Ed?.()?.getCurrentPageShapes().length ?? null,
    };
  });
// Run 4 (HEAD dist): S3d fresh-session reload, S5 two-tab sync, then delete every page this verification created.
import { installEditorFinder, readState, closeRoamDialogs, openPage, snapshotEditor, attachLogs, tryWait, REL } from "./common.mjs";

const loadedFn = (t) => document.querySelector(".rm-title-display")?.innerText.trim() === t && (window.__eng1955Ed?.()?.getCurrentPageShapes().length ?? 0) >= 6;

export default {
  async ready({ page }) {
    await closeRoamDialogs(page);
    return page.evaluate(() => Boolean(window.roamAlphaAPI && window.roamjs?.extension?.queryBuilder));
  },
  async run({ page, context, outDir }) {
    const logs = attachLogs(page);
    await installEditorFinder(page);
    const { T, U } = readState();
    const out = { page: T.cloud };
    await openPage(page, U.cloud);
    out.s3dLoaded = await tryWait(page, loadedFn, T.cloud, 60000, "shapes");
    await page.waitForTimeout(2000);
    out.s3d = await snapshotEditor(page, T.cloud);
    await page.screenshot({ path: `${outDir}/s3d-head-reload.png` });

    // S5: second tab in the same context.
    const p2 = await context.newPage();
    const logs2 = attachLogs(p2);
    await p2.goto(page.url());
    out.s5Tab2Dg = await tryWait(p2, () => Boolean(window.roamjs?.extension?.queryBuilder), null, 60000, "DG in tab 2");
    let other = null;
    if (out.s5Tab2Dg) {
      await installEditorFinder(p2);
      await openPage(p2, U.cloud);
      out.s5Tab2Loaded = await tryWait(p2, loadedFn, T.cloud, 60000, "tab2 shapes");
      other = p2;
    } else {
      out.s5Mode = "sidebar";
      await page.evaluate(() => { window.__eng1955Main = window.__eng1955Ed(); return true; });
      await page.evaluate((uid) => window.roamAlphaAPI.ui.rightSidebar.addWindow({ window: { type: "outline", "block-uid": uid } }), U.cloud);
      out.s5SidebarEditors = await tryWait(page, () => window.__eng1955Editors().filter(Boolean).length >= 2, null, 60000, "sidebar editor");
    }
    if (other) {
      out.s5Mode = "two-tabs";
      out.s5Create = await other.evaluate((rel) => {
        const ed = window.__eng1955Ed();
        const id = "shape:eng1955TabTwo";
        ed.createShape({ id, type: "discourse-relation", x: 0, y: 0, props: { text: "Supports", relationTypeId: rel, start: { x: 0, y: 0 }, end: { x: 0, y: 0 } } });
        const bp = { normalizedAnchor: { x: 0.5, y: 0.5 }, isPrecise: false, isExact: false };
        ed.createBinding({ type: "discourse-relation", fromId: id, toId: "shape:eng1955E", props: { terminal: "start", ...bp } });
        ed.createBinding({ type: "discourse-relation", fromId: id, toId: "shape:eng1955A", props: { terminal: "end", ...bp } });
        return ed.getShape(id)?.type;
      }, REL.supports);
      out.s5SeenInTab1 = await tryWait(page, () => {
        const ed = window.__eng1955Ed();
        const s = ed?.getShape("shape:eng1955TabTwo");
        return Boolean(s && ed.getBindingsFromShape(s.id, "discourse-relation").length === 2);
      }, null, 20000, "arrow in tab 1");
      out.s5Tab1Shape = await page.evaluate(() => { const s = window.__eng1955Ed().getShape("shape:eng1955TabTwo"); return s ? { type: s.type, relationTypeId: s.props.relationTypeId } : null; });
      // Edit a legacy arrow in tab 1 and confirm tab 2 sees it.
      await page.evaluate(() => { const ed = window.__eng1955Ed(); ed.updateShapes([{ id: "shape:eng1955ArrAQ", type: "yd7pX2bvn", props: { bend: -40 } }]); return true; });
      out.s5LegacyEditSeenInTab2 = await tryWait(other, () => window.__eng1955Ed()?.getShape("shape:eng1955ArrAQ")?.props.bend === -40, null, 20000, "legacy edit in tab 2");
      await page.evaluate(() => { window.__eng1955Ed().zoomToFit(); return true; });
      await page.waitForTimeout(800);
      await page.screenshot({ path: `${outDir}/s5-tab1.png` });
      await other.screenshot({ path: `${outDir}/s5-tab2.png` });
      await other.close();
    }
    out.logsTab1 = logs.slice(0, 20);
    out.logsTab2 = logs2.filter((l) => /valid|shape|binding|sync|relation/i.test(l)).slice(0, 20);
    return out;
  },
  async cleanup({ page }) {
    const { createdPages } = readState();
    const res = {};
    for (const uid of [...new Set(createdPages)]) {
      res[uid] = await page.evaluate(async (u) => {
        const title = window.roamAlphaAPI.pull("[:node/title]", [":block/uid", u])?.[":node/title"];
        if (!title) return "absent";
        if (!/eng1955/.test(title)) return "skipped-not-ours";
        await window.roamAlphaAPI.data.page.delete({ page: { uid: u } });
        return "deleted";
      }, uid);
    }
    await page.waitForTimeout(2000);
    res.remaining = await page.evaluate(() => window.roamAlphaAPI.q(`[:find (count ?p) . :where [?p :node/title ?t] [(clojure.string/includes? ?t "eng1955")]]`));
    return res;
  },
};
// Run 6 (HEAD dist): reload check and S5 via main window + right sidebar, then delete every page this verification created.
import { installEditorFinder, readState, closeRoamDialogs, openPage, snapshotEditor, attachLogs, tryWait, REL } from "./common.mjs";

const loadedFn = (t) => document.querySelector(".rm-title-display")?.innerText.trim() === t && (window.__eng1955Ed?.()?.getCurrentPageShapes().length ?? 0) >= 6;

export default {
  async ready({ page }) {
    await closeRoamDialogs(page);
    return page.evaluate(() => Boolean(window.roamAlphaAPI && window.roamjs?.extension?.queryBuilder));
