// Run 1 (dist-main): S1 cloud canvas with uid-typed arrows; S4a local canvas with uid-typed arrow.
import { installEditorFinder, readState, writeState, REL, NODE, waitFor, tryWait, closeRoamDialogs, uidOf, openPage, snapshotEditor, rawPageStore, attachLogs, relevant } from "./common.mjs";

const TS = Date.now();
const T = {
  cloud: `Canvas/eng1955-cloud-${TS}`,
  local: `Canvas/eng1955-local-${TS}`,
  a: `[[CLM]] - eng1955 claim A ${TS}`,
  b: `[[CLM]] - eng1955 claim B ${TS}`,
  q: `[[QUE]] - eng1955 question ${TS}`,
  e: `[[EVD]] - eng1955 evidence ${TS} - none`,
};

const seedCanvas = (page, title, nodes, arrows) =>
  page.evaluate(({ title, nodes, arrows }) => {
    const ed = window.__eng1955Ed();
    ed.createShapes(nodes.map((n) => ({ id: n.id, type: "discourse-node", x: n.x, y: n.y, props: { uid: n.uid, title: n.title, nodeTypeId: n.nodeTypeId, w: 220, h: 90 } })));
    for (const a of arrows) {
      ed.createShapes([{ id: a.id, type: a.rel, x: 0, y: 0, props: { text: a.label, start: { x: 0, y: 0 }, end: { x: 10, y: 10 } } }]);
      ed.createBindings([
        { type: a.rel, fromId: a.id, toId: a.from, props: { terminal: "start", normalizedAnchor: { x: 0.5, y: 0.5 }, isExact: false, isPrecise: false } },
        { type: a.rel, fromId: a.id, toId: a.to, props: { terminal: "end", normalizedAnchor: { x: 0.5, y: 0.5 }, isExact: false, isPrecise: false } },
      ]);
    }
    ed.zoomToFit();
    return true;
  }, { title, nodes, arrows });

export default {
  async ready({ page }) {
    await closeRoamDialogs(page);
    return page.evaluate(() => Boolean(window.roamAlphaAPI && window.roamjs?.extension?.queryBuilder));
  },
  async run({ page, outDir }) {
    const logs = attachLogs(page);
    await installEditorFinder(page);
    const out = { titles: T };
    for (const t of Object.values(T)) await page.evaluate((title) => window.roamAlphaAPI.data.page.create({ page: { title } }), t);
    await page.waitForTimeout(1500);
    const U = {};
    for (const [k, t] of Object.entries(T)) U[k] = await uidOf(page, t);
    out.uids = U;
    const prev = readState();
    writeState({ T, U, createdPages: [...(prev.createdPages || []), ...Object.values(U)] });

    const nodes = [
      { id: "shape:eng1955A", uid: U.a, title: T.a, nodeTypeId: NODE.claim, x: 0, y: 0 },
      { id: "shape:eng1955B", uid: U.b, title: T.b, nodeTypeId: NODE.claim, x: 500, y: 0 },
      { id: "shape:eng1955Q", uid: U.q, title: T.q, nodeTypeId: NODE.question, x: 250, y: 350 },
      { id: "shape:eng1955E", uid: U.e, title: T.e, nodeTypeId: NODE.evidence, x: -250, y: 350 },
    ];
    const arrows = [
      { id: "shape:eng1955ArrEA", rel: REL.supports, label: "Supports", from: "shape:eng1955E", to: "shape:eng1955A" },
      { id: "shape:eng1955ArrAQ", rel: REL.informs, label: "Informs", from: "shape:eng1955A", to: "shape:eng1955Q" },
    ];

    // --- S1: cloud canvas ---
    await openPage(page, U.cloud);
    await waitFor(page, (t) => Boolean(window.__eng1955Ed?.()) && document.querySelector(".rm-title-display")?.innerText.trim() === t, T.cloud, 60000, "cloud editor");
    await closeRoamDialogs(page);
    out.utilKeys = await page.evaluate(() => Object.keys(window.__eng1955Ed().shapeUtils));
    out.bindingKeys = await page.evaluate(() => Object.keys(window.__eng1955Ed().bindingUtils));
    if (process.env.ENG1955_PROBE_ONLY) return out;
    await seedCanvas(page, T.cloud, nodes, arrows);
    await page.waitForTimeout(2500);
    out.s1LocalBefore = await rawPageStore(page, U.cloud);
    const editorBefore = await page.evaluate((t) => { window.__eng1955Prev = window.__eng1955Ed(); return true; }, T.cloud);
    await page.locator("[data-testid='main-menu.button']").first().click();
    await page.waitForTimeout(500);
    await page.getByText("(Beta) Use cloud canvas").first().click();
    await page.waitForTimeout(500);
    await page.getByRole("button", { name: "Move to cloud sync" }).click();
    out.s1SwitchedEditor = await tryWait(page, (t) => window.__eng1955Ed() && window.__eng1955Ed() !== window.__eng1955Prev && window.__eng1955Ed().getCurrentPageShapes().length >= 5, T.cloud, 60000, "cloud editor with shapes");
    await page.waitForTimeout(15000); // let the room receive and persist
