// r4 (HEAD): on the legacy cloud room — R1 drag-handle (cloud), R3b moves, R4 duplicate, R5 export.
import fs from "node:fs";
import { installEditorFinder, closeRoamDialogs, openPage, recorder, readState2, allLogs, errorsIn, maxDepth, waitCanvas, zoomFit, shapeCenter, mouseDrag, relationShapes, nodeShapes, storedRelations, autoGeneratedPages, readAutoCanvasUI, sleep } from "./common2.mjs";

const relSummary = (rels) => rels.map((r) => `${r.id}|${r.type}|${r.relationTypeId ?? "-"}|${r.index}|${r.bindingTypes.join("+")}`);

export default {
  async ready({ page }) {
    await closeRoamDialogs(page);
    return page.evaluate(() => Boolean(window.roamAlphaAPI && window.roamjs?.extension?.queryBuilder));
  },
  async run({ page, outDir }) {
    const logs = allLogs(page);
    await installEditorFinder(page);
    const { out, step } = recorder(outDir);
    const { pages } = readState2();
    const nodeUids = [pages.e3.uid, pages.c3.uid];
    await step("autoCanvasRelationsInitial", () => readAutoCanvasUI(page));
    await openPage(page, pages.cloud.uid);
    await step("loaded", () => waitCanvas(page, pages.cloud.title, 6));
    await sleep(page, 3000);
    await zoomFit(page);
    await step("before", async () => ({ rels: relSummary(await relationShapes(page)), nodes: await nodeShapes(page), stored: await storedRelations(page, nodeUids) }));

    // R1 cloud: drag-handle overlay + relation type dropdown.
    let mark = logs.length;
    await step("r1CloudDragHandle", async () => {
      const e = await shapeCenter(page, "shape:r3E");
      await page.mouse.click(e.x, e.y);
      await sleep(page, 600);
      const selected = await page.evaluate(() => window.__eng1955Ed().getSelectedShapeIds());
      const handles = page.locator(".roamjs-tldraw-canvas-container .cursor-crosshair");
      const n = await handles.count();
      if (!n) return { selected, handles: 0 };
      let best = null;
      for (let i = 0; i < n; i += 1) { const b = await handles.nth(i).boundingBox(); if (b && (!best || b.x > best.x)) best = b; }
      const c = await shapeCenter(page, "shape:r3C");
      await mouseDrag(page, { x: best.x + best.width / 2, y: best.y + best.height / 2 }, c, 15);
      await sleep(page, 600);
      const options = await page.locator(".roamjs-tldraw-canvas-container button", { hasText: /./ }).filter({ has: page.locator("span.rounded-full") }).allInnerTexts();
      const before = (await relationShapes(page)).map((r) => r.id);
      await page.locator(".roamjs-tldraw-canvas-container button", { hasText: /^Supports$/ }).first().click();
      await sleep(page, 4000);
      const after = await relationShapes(page);
      return { selected, handles: n, dropdownOptions: options, created: after.filter((r) => !before.includes(r.id)), stored: await storedRelations(page, nodeUids), autoGenPages: await autoGeneratedPages(page) };
    });
    out.r1CloudErrors = errorsIn(logs, mark);
    await page.screenshot({ path: `${outDir}/r1-cloud-draghandle.png` });

    // R3b: move nodes around with real mouse drags.
    mark = logs.length;
    out.r3bMoves = [];
    const moves = [["shape:r3C", { dx: 0, dy: 180 }], ["shape:r3E", { dx: 120, dy: -120 }], ["shape:r3C", { dx: -200, dy: -60 }], ["shape:r3E", { dx: -80, dy: 160 }], ["shape:r3C", { dx: 150, dy: 0 }]];
    for (const [id, d] of moves) {
      await step("_move", async () => {
        await page.evaluate(() => { window.__eng1955Ed().selectNone(); return true; });
        const c = await shapeCenter(page, id);
        await mouseDrag(page, { x: c.x - 60, y: c.y + 20 }, { x: c.x - 60 + d.dx, y: c.y + 20 + d.dy }, 10);
        await sleep(page, 800);
        out.r3bMoves.push({ id, nodes: await nodeShapes(page), rels: relSummary(await relationShapes(page)) });
        return true;
      });
    }
    await sleep(page, 2000);
    out.r3bMaxDepthErrors = maxDepth(logs.slice(mark));
    out.r3bErrors = errorsIn(logs, mark);
    out.r3bRendered = await page.evaluate(() => Array.from(document.querySelectorAll(".roamjs-tldraw-canvas-container .tl-shape")).map((e) => e.getAttribute("data-shape-type")));
    await zoomFit(page);
    await page.screenshot({ path: `${outDir}/r3b-after-moves.png` });

    // R4: select a legacy arrow plus both nodes, Cmd+D.
    mark = logs.length;
    await step("r4Duplicate", async () => {
      const beforeIds = await page.evaluate(() => window.__eng1955Ed().getCurrentPageShapes().map((s) => s.id));
      await page.evaluate(() => { const ed = window.__eng1955Ed(); ed.select("shape:r3Supports", "shape:r3E", "shape:r3C"); return ed.getSelectedShapeIds(); });
      await page.locator(".roamjs-tldraw-canvas-container .tl-canvas").first().focus().catch(() => {});
      await page.keyboard.press("Meta+d");
      await sleep(page, 1500);
      let via = "Meta+d";
      let newIds = await page.evaluate((b) => window.__eng1955Ed().getCurrentPageShapes().map((s) => s.id).filter((i) => !b.includes(i)), beforeIds);
      if (!newIds.length) {
        via = "editor.duplicateShapes";
        await page.evaluate(() => { const ed = window.__eng1955Ed(); ed.duplicateShapes(["shape:r3Supports", "shape:r3E", "shape:r3C"]); return true; });
        await sleep(page, 1500);
        newIds = await page.evaluate((b) => window.__eng1955Ed().getCurrentPageShapes().map((s) => s.id).filter((i) => !b.includes(i)), beforeIds);
      }
      const rels = await relationShapes(page);
      return { via, newIds, duplicateArrows: rels.filter((r) => newIds.includes(r.id)), newNodes: (await nodeShapes(page)).filter((n) => newIds.includes(n.id)) };
    });
    await sleep(page, 5000);
    // Remount: leave and reopen the room.
    await openPage(page, pages.e3.uid);
    await sleep(page, 2500);
    await openPage(page, pages.cloud.uid);
    await step("r4AfterRemount", async () => ({ loaded: await waitCanvas(page, pages.cloud.title, 6), rels: relSummary(await relationShapes(page)), nodeCount: (await nodeShapes(page)).length }));
    await sleep(page, 2000);
    out.r4Errors = errorsIn(logs, mark);
    await zoomFit(page);
    await page.screenshot({ path: `${outDir}/r4-after-remount.png` });

    // R5: export via tldraw main menu (Export as -> SVG), plus editor SVG for comparison.
    mark = logs.length;
    await step("r5Export", async () => {
      await page.evaluate(() => { window.__eng1955Ed().selectNone(); return true; });
      await page.locator("[data-testid='main-menu.button']").first().click();
      await sleep(page, 500);
      const menuTexts = await page.locator(".tlui-menu [role='menuitem'], .tlui-menu button").allInnerTexts();
      await page.locator(".tlui-menu").getByText(/^Export as$/).first().click().catch(async () => page.locator(".tlui-menu").getByText(/Export as/).first().hover());
      await sleep(page, 500);
      const subTexts = await page.locator(".tlui-menu [role='menuitem'], .tlui-menu button").allInnerTexts();
      const dl = page.waitForEvent("download", { timeout: 20000 });
      await page.locator(".tlui-menu").getByText(/^SVG$/).first().click();
      const d = await dl;
      const file = `${outDir}/r5-export.svg`;
      await d.saveAs(file);
      const svg = fs.readFileSync(file, "utf8");
      const count = (re) => (svg.match(re) || []).length;
      const editorSvg = await page.evaluate(async () => {
        const ed = window.__eng1955Ed();
        const r = await ed.getSvgString([...ed.getCurrentPageShapeIds()]);
        return r?.svg || null;
      });
      if (editorSvg) fs.writeFileSync(`${outDir}/r5-editor-getSvgString.svg`, editorSvg);
      const ecount = (re) => ((editorSvg || "").match(re) || []).length;
      return {
        menuTexts: menuTexts.slice(0, 30), subTexts: subTexts.slice(0, 40), suggestedFilename: d.suggestedFilename(), bytes: svg.length,
        exportLabelCounts: { Supports: count(/>Supports</g), opposes: count(/>opposes</g), Corroborates: count(/>Corroborates</g) },
        editorSvgLabelCounts: { Supports: ecount(/>Supports</g), opposes: ecount(/>opposes</g), Corroborates: ecount(/>Corroborates</g) },
      };
    });
    out.r5Errors = errorsIn(logs, mark);
    await page.screenshot({ path: `${outDir}/r5-after-export.png` });
    out.maxDepthTotal = maxDepth(logs);
    out.pushResultTotal = logs.filter((l) => /Received push_result/.test(l.text)).length;
    out.allErrors = errorsIn(logs).slice(0, 40);
    return out;
  },
};

