      const count = (re) => (svg.match(re) || []).length;
      return { ...r, labels: { Supports: count(/>Supports</g), opposes: count(/>opposes</g), Corroborates: count(/>Corroborates</g) }, paths: count(/<path/g), nodeTitles: count(/eng1955r/g) };
    });
