    const N = (k, id, typ, x, y) => ({ id, uid: U[k], title: T[k], nodeTypeId: typ, x, y });

    // ---------- R1 local ----------
    await openPage(page, U.l1);
    await step("l1Ready", () => waitCanvas(page, T.l1));
    await closeRoamDialogs(page);
    await addNodes(page, [N("e1", "shape:e1", NODE.evidence, 0, 0), N("c1", "shape:c1", NODE.claim, 600, 0), N("q1", "shape:q1", NODE.question, 600, 400), N("e2", "shape:e2", NODE.evidence, 0, 800), N("c2", "shape:c2", NODE.claim, 600, 800)]);
    await sleep(page, 1500);
    await zoomFit(page);
    out.autoGenBefore = await autoGenBlocks(page);

    let mark = logs.length;
    await step("r1DragHandle", async () => {
      const b = await relIds(page);
      const r = await dragHandle(page, "shape:e1", "shape:c1", "Supports");
      return { ...r, created: relSummary(await newRels(page, b)), autoGen: await autoGenBlocks(page), errors: errorsIn(logs, mark) };
    });
    await page.screenshot({ path: `${outDir}/r1-local-draghandle.png` });

    mark = logs.length;
    await step("r1Tool", async () => {
      const b = await relIds(page);
      await page.evaluate(() => { window.__eng1955Ed().selectNone(); return true; });
      await sleep(page, 500);
      const rows = await page.locator(".tlui-style-panel__row").allInnerTexts();
      await page.locator(".tlui-style-panel__row", { hasText: /^\s*Informs\s*$/ }).first().click();
      await sleep(page, 500);
      const tool = await page.evaluate(() => window.__eng1955Ed().getCurrentToolId());
      const from = await shapeCenter(page, "shape:c1");
      const to = await shapeCenter(page, "shape:q1");
      await mouseDrag(page, from, to, 15);
      await sleep(page, 4000);
      return { panelRows: rows.map((x) => x.trim()).slice(0, 40), tool, created: relSummary(await newRels(page, b)), autoGen: await autoGenBlocks(page), errors: errorsIn(logs, mark) };
    });
    await page.evaluate(() => { window.__eng1955Ed().setCurrentTool("select"); return true; });
    await page.screenshot({ path: `${outDir}/r1-local-tool.png` });

    mark = logs.length;
    await step("r1Convert", async () => {
      await page.evaluate(() => { window.__eng1955Ed().selectNone(); return true; });
      const b = await relIds(page);
      let via = "toolbar";
      const btn = page.locator("[data-testid='tools.arrow']").first();
      if (await btn.count()) await btn.click(); else { via = "editor.setCurrentTool"; await page.evaluate(() => { window.__eng1955Ed().setCurrentTool("arrow"); return true; }); }
      await sleep(page, 400);
      await mouseDrag(page, await shapeCenter(page, "shape:e2"), await shapeCenter(page, "shape:c2"), 15);
      await sleep(page, 800);
      const plain = (await newRels(page, b)).find((r) => r.type === "arrow");
      if (!plain) return { via, error: "no plain arrow created", created: relSummary(await newRels(page, b)) };
      await page.evaluate(() => { window.__eng1955Ed().setCurrentTool("select"); return true; });
      await page.evaluate((id) => { window.__eng1955Ed().select(id); return true; }, plain.id);
      const mid = await shapeCenter(page, plain.id);
      await page.mouse.click(mid.x, mid.y, { button: "right" });
      await sleep(page, 700);
      const menu = await page.evaluate(() => Array.from(document.querySelectorAll("[data-testid]")).filter((e) => /context-menu/.test(e.getAttribute("data-testid"))).map((e) => `${e.getAttribute("data-testid")}|${(e.innerText || "").split("\n")[0]}`));
      const sub = page.locator("[data-testid='context-menu-sub.relation-submenu-button']");
      if (await sub.count()) await sub.click(); else await page.locator(".tlui-menu").getByText(/^Relation$/).first().click();
      await sleep(page, 600);
      const subItems = await page.evaluate(() => Array.from(document.querySelectorAll("[data-testid^='context-menu.relation-']")).map((e) => (e.innerText || "").trim()));
      await page.locator("[data-testid^='context-menu.relation-']", { hasText: /^Supports$/ }).first().click();
      await sleep(page, 4000);
      const after = await relationShapes(page);
      return { via, plainArrow: plain.id, plainStillExists: after.some((r) => r.id === plain.id), menu: menu.slice(0, 30), subItems, created: relSummary(after.filter((r) => !b.includes(r.id))), autoGen: await autoGenBlocks(page), errors: errorsIn(logs, mark) };
    });
    await page.screenshot({ path: `${outDir}/r1-local-convert.png` });

    // Node card "Add node to canvas" (auto relations OFF -> drawRelationArrow).
    mark = logs.length;
    await step("r1NodePanel", async () => {
      await page.evaluate(() => { const ed = window.__eng1955Ed(); ed.selectNone(); ed.deleteShapes(["shape:c1"]); return true; });
      await sleep(page, 1000);
      const b = await relIds(page);
      const autoGenBefore = await autoGenBlocks(page);
      const e = await shapeCenter(page, "shape:e1");
      await page.mouse.click(e.x, e.y);
      await sleep(page, 1000);
      const addBtn = page.locator("button[title='Add node to canvas']");
      await addBtn.first().waitFor({ state: "visible", timeout: 20000 });
      const panelText = (await page.locator(".dg-node-style-panel").first().innerText()).replace(/\s+/g, " ").slice(0, 300);
      const n = await addBtn.count();
      await addBtn.first().click();
      await sleep(page, 4000);
      const nodes = await nodeShapes(page);
      const autoGenAfter = await autoGenBlocks(page);
      return { addButtons: n, panelText, nodesNow: nodes.map((x) => x.uid === U.c1 ? `c1:${x.id}` : x.id), created: relSummary(await newRels(page, b)), autoGenBlockCountBefore: autoGenBefore.reduce((a, p) => a + p.blocks.length, 0), autoGenBlockCountAfter: autoGenAfter.reduce((a, p) => a + p.blocks.length, 0), errors: errorsIn(logs, mark) };
    });
    await page.screenshot({ path: `${outDir}/r1-local-nodepanel.png` });

    // Auto canvas relations: turn ON, re-add claim one programmatically.
    out.autoSetOn = await step("autoSetOn", () => setAutoCanvasUI(page, true));
    await openPage(page, U.l1);
    await waitCanvas(page, T.l1, 4);
    await sleep(page, 1500);
    mark = logs.length;
    await step("r1Auto", async () => {
      const c1 = await page.evaluate((uid) => window.__eng1955Ed().getCurrentPageShapes().find((s) => s.props?.uid === uid)?.id, U.c1);
      if (c1) await page.evaluate((id) => { window.__eng1955Ed().deleteShapes([id]); return true; }, c1);
      await sleep(page, 1000);
      const b = await relIds(page);
      await addNodes(page, [N("c1", "shape:c1b", NODE.claim, 600, 0)]);
      await sleep(page, 6000);
      return { removed: c1, created: relSummary(await newRels(page, b)), errors: errorsIn(logs, mark) };
    });
    await zoomFit(page);
    await page.screenshot({ path: `${outDir}/r1-local-auto.png` });
    out.r1LocalFinal = relSummary(await relationShapes(page));

    // ---------- R2: auto ON, local -> cloud ----------
    mark = logs.length;
    await openPage(page, U.l2);
    await step("l2Ready", () => waitCanvas(page, T.l2));
    await closeRoamDialogs(page);
    const r2Nodes = [N("e1", "shape:r2e1", NODE.evidence, 0, 0), N("c1", "shape:r2c1", NODE.claim, 600, 0), N("q1", "shape:r2q1", NODE.question, 600, 400), N("e2", "shape:r2e2", NODE.evidence, 0, 800), N("c2", "shape:r2c2", NODE.claim, 600, 800)];
    for (const n of r2Nodes) { await addNodes(page, [n]); await sleep(page, 2500); }
    await sleep(page, 3000);
    await zoomFit(page);
    await step("r2BeforeSwitch", async () => { const r = await relationShapes(page); return { rels: relSummary(r), pairs: pairCounts(r) }; });
    await page.screenshot({ path: `${outDir}/r2-local-before.png` });
    await step("r2Switch", async () => {
      await page.evaluate(() => { window.__eng1955Prev = window.__eng1955Ed(); return true; });
      await page.locator("[data-testid='main-menu.button']").first().click();
      await sleep(page, 500);
      await page.getByText("(Beta) Use cloud canvas").first().click();
      await sleep(page, 500);
      await page.getByRole("button", { name: "Move to cloud sync" }).click();
      const start = Date.now();
      while (Date.now() - start < 60000) {
        if (await page.evaluate(() => window.__eng1955Ed() && window.__eng1955Ed() !== window.__eng1955Prev && window.__eng1955Ed().getCurrentPageShapes().length >= 5)) return true;
        await sleep(page, 400);
      }
      return false;
    });
    await sleep(page, 15000);
    await step("r2AfterSwitch", async () => { const r = await relationShapes(page); return { cloudIcon: await page.evaluate(() => Boolean(document.querySelector(".roamjs-tldraw-canvas-container [title='Using cloud canvas']"))), rels: relSummary(r), pairs: pairCounts(r) }; });
    await zoomFit(page);
    await page.screenshot({ path: `${outDir}/r2-cloud-after-switch.png` });
    await openPage(page, U.e1);
    await sleep(page, 2500);
    await openPage(page, U.l2);
    await step("r2AfterRemount", async () => { await waitCanvas(page, T.l2, 5); await sleep(page, 8000); const r = await relationShapes(page); return { rels: relSummary(r), pairs: pairCounts(r) }; });
    await zoomFit(page);
    await page.screenshot({ path: `${outDir}/r2-cloud-after-remount.png` });
    out.r2Errors = errorsIn(logs, mark);

    // Restore auto canvas relations before R3a.
    out.autoRestore = await step("autoRestore", () => setAutoCanvasUI(page, out.autoInitial === true));
    out.autoFinal = await step("autoFinal", () => readAutoCanvasUI(page));

    // ---------- R3a: local evidence/claim with several arrows, move around ----------
    mark = logs.length;
    await openPage(page, U.l3);
    await step("l3Ready", () => waitCanvas(page, T.l3));
    await closeRoamDialogs(page);
    await addNodes(page, [N("e4", "shape:r3aE", NODE.evidence, 0, 0), N("c4", "shape:r3aC", NODE.claim, 600, 0)]);
    await sleep(page, 1500);
    await zoomFit(page);
    for (const label of ["Supports", "opposes", "Corroborates"]) await step(`r3aDrag_${label}`, () => dragHandle(page, "shape:r3aE", "shape:r3aC", label));
    await step("r3aPlain", () => page.evaluate(() => {
      const ed = window.__eng1955Ed();
      const bp = (t) => ({ terminal: t, normalizedAnchor: { x: 0.5, y: 0.5 }, isExact: false, isPrecise: false });
      ed.createShapes([{ id: "shape:r3aPlain", type: "arrow", x: 0, y: 0, props: { bend: 80 } }]);
      ed.createBindings([{ type: "arrow", fromId: "shape:r3aPlain", toId: "shape:r3aE", props: bp("start") }, { type: "arrow", fromId: "shape:r3aPlain", toId: "shape:r3aC", props: bp("end") }]);
      return true;
    }));
    await sleep(page, 1000);
    out.r3aBefore = { rels: relSummary(await relationShapes(page)), nodes: await nodeShapes(page) };
    out.r3aMoves = [];
    const moves = [["shape:r3aC", 0, 180], ["shape:r3aE", 120, -120], ["shape:r3aC", -200, -60], ["shape:r3aE", -80, 160], ["shape:r3aC", 150, 0]];
    for (const [id, dx, dy] of moves) {
      await step("_m", async () => {
        await page.evaluate(() => { window.__eng1955Ed().selectNone(); return true; });
        const c = await shapeCenter(page, id);
        await mouseDrag(page, { x: c.x - 60, y: c.y + 20 }, { x: c.x - 60 + dx, y: c.y + 20 + dy }, 10);
        await sleep(page, 800);
        out.r3aMoves.push({ id, nodes: (await nodeShapes(page)).map((n) => `${n.id}@${n.index}(${n.x},${n.y})`), rels: (await relationShapes(page)).map((r) => `${r.id.slice(6, 14)}:${r.index}`) });
        return true;
      });
    }
    await sleep(page, 2000);
    out.r3aRendered = await page.evaluate(() => Array.from(document.querySelectorAll(".roamjs-tldraw-canvas-container .tl-shape")).map((e) => e.getAttribute("data-shape-type")));
    out.r3aMaxDepth = maxDepth(logs.slice(mark));
    out.r3aErrors = errorsIn(logs, mark);
    await zoomFit(page);
    await page.screenshot({ path: `${outDir}/r3a-local-after-moves.png` });
    out.autoGenFinal = await autoGenBlocks(page);
    out.autoGenPages = await autoGeneratedPages(page);
    out.maxDepthTotal = maxDepth(logs);
    out.allErrors = errorsIn(logs).slice(0, 40);
    return out;
  },
};

